import{_ as t,o,c as s,ag as n}from"./chunks/framework.B9unkguw.js";const c=JSON.parse('{"title":"QGroundControl 설정 문제 해결","description":"","frontmatter":{},"headers":[],"relativePath":"ko/qgc-user-guide/troubleshooting/qgc_setup.md","filePath":"ko/qgc-user-guide/troubleshooting/qgc_setup.md"}'),a={name:"ko/qgc-user-guide/troubleshooting/qgc_setup.md"};function i(r,e,l,d,p,u){return o(),s("div",null,e[0]||(e[0]=[n('<h1 id="qgroundcontrol-설정-문제-해결" tabindex="-1">QGroundControl 설정 문제 해결 <a class="header-anchor" href="#qgroundcontrol-설정-문제-해결" aria-label="Permalink to &quot;QGroundControl 설정 문제 해결&quot;">​</a></h1><p>호스트 컴퓨터에서 <em>QGroundControl</em>의 설정 및 설치와 관련된 문제 해결 방법을 설명합니다.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p><em>QGroundControl</em>을 <strong>사용</strong>하여 기체 연동시 발생하는 문제는 <a href="./../troubleshooting/qgc_usage.html">QGroundControl 기체 연동 문제</a>에서 설명합니다.</p></div><h2 id="opengl_troubleshooting" tabindex="-1">Windows: UI 렌더링/비디오 드라이버 문제 <a class="header-anchor" href="#opengl_troubleshooting" aria-label="Permalink to &quot;Windows: UI 렌더링/비디오 드라이버 문제 {#opengl_troubleshooting}&quot;">​</a></h2><p>Windows에서 UI 렌더링 문제 또는 비디오 드라이버 충돌이 발생하는 경우에는 &quot;비정상적&quot; OpenGL 드라이버가 원인일 수 있습니다. <em>QGroundControl</em>은 &quot;안전한&quot; 동영상 모드에서 <em>QGroundControl</em>을 시작하는 데 사용할 수 있는 3가지 단축키를 제공합니다(순서대로 시도).</p><ul><li><strong>QGroundControl:</strong> QGroundControl은 OpenGL 그래픽 드라이버를 직접 사용합니다.</li><li><strong>GPU 호환성 모드:</strong> QGC는 DirectX 위에 OpenGL을 구현하는 ANGLE 드라이버를 사용합니다.</li><li><strong>GPU 안전 모드:</strong> QGroundControl은 UI에 소프트웨어 래스터라이저를 사용합니다(매우 느림).</li></ul><h2 id="waiting_for_connection" tabindex="-1">Windows: WiFi 기체 연결 불량 <a class="header-anchor" href="#waiting_for_connection" aria-label="Permalink to &quot;Windows: WiFi 기체 연결 불량 {#waiting_for_connection}&quot;">​</a></h2><p>Wi-Fi를 통해 기체 연결시 <em>QGroundControl</em>이 영구적으로 유지되는 경우(예: <em>기체 연결 대기</em>), 가능한 원인은 IP 트래픽이 방화벽 소프트웨어에 의해 차단되기 때문일 수 있습니다.</p><p>해결책은 방화벽을 통해 <em>QGroundControl</em> 앱을 허용하는 것입니다.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>연결을 허용하기 위해 네트워크 프로필을 공개에서 비공개로 간단히 전환할 수 있지만, PC가 네트워크에 노출되므로 주의하십시오.</p></div><p><em>Windows Defender</em>를 사용하는 경우:</p><ul><li><p><strong>시작</strong> 표시줄에서 다음을 입력/선택합니다.</p></li><li><p>스크롤하여 <em>방화벽을 통해 앱 허용</em> 옵션을 선택합니다.</p></li><li><p><em>QGroundControl</em>을 선택하고 <em>액세스</em> 선택기를 <strong>허용</strong>으로 변경합니다.</p><p><strong>Tip</strong> 프로그램은 파일 이름이 아닌 설명의 알파벳 순서로 나열됩니다. <em>QGroundControl 개발 팀에서 제공하는 오픈 소스 지상 관제 앱</em></p></li></ul><h2 id="missing_gstreamer" tabindex="-1">Ubuntu: 비디오 스트리밍 실패(Gstreamer 누락) <a class="header-anchor" href="#missing_gstreamer" aria-label="Permalink to &quot;Ubuntu: 비디오 스트리밍 실패(Gstreamer 누락) {#missing_gstreamer}&quot;">​</a></h2><p>Ubuntu에서 비디오 스트림을 보려면 <em>Gstreamer</em> 구성요소를 설치하여야 합니다. 이것들이 설치되어 있지 않으면, <em>QGroundControl</em>이 gstreamer 노드를 생성할 수 없고 다음과 같은 에러가 발생합니다.</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">VideoReceiver::start</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">()가 실패했습니다. gst_element_factory_make(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">&#39;avdec_h264&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) 오류</span></span></code></pre></div><p><a href="./../getting_started/download_and_install.html#ubuntu">Ubuntu용 다운로드/설치 지침</a>에는 <em>GStreamer</em> 설정 정보가 포함되어 있습니다.</p><h2 id="dual_vga" tabindex="-1">Ubuntu 18.04: 듀얼 비디오 어댑터 시스템에서 비디오 스트리밍 실패 <a class="header-anchor" href="#dual_vga" aria-label="Permalink to &quot;Ubuntu 18.04: 듀얼 비디오 어댑터 시스템에서 비디오 스트리밍 실패 {#dual_vga}&quot;">​</a></h2><p>The version of GStreamer in Ubuntu 18.04 has a bug that prevents video displaying when using a VA API based decoder (i.e. vaapih264dec etc.) on systems that have both Intel and NVidia video display adapters.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>더 일반적인 문제는 Intel 및 NVidia VGA가 있는 Ubuntu 18.04에서 발생하는 것으로 알려져 있지만, 모든 Linux 시스템 및 기타 유형의 (이중) VGA에서 발생할 수 있습니다.</p></div><p>이 경우 <em>QGroundControl</em> 실행하는 가장 쉬운 방법은 다음 명령어를 사용하여 시작하는 것입니다.</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">LIBVA_DRIVER_NAME</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">fakedriver</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> ./QGroundControl</span></span></code></pre></div><p>다른 대안은 VGA 중 하나를 비활성화하거나 VA API 구성 요소를 제거하거나 GStreamer 1.16으로 업그레이드하는 것입니다(Ubuntu 18.04에서는 이를 수행하는 쉬운 방법이 없습니다.</p>',22)]))}const g=t(a,[["render",i]]);export{c as __pageData,g as default};
